cd /tmp && perl -e '
use strict; my $B="/workspace/dataset/test11_executable";
sub cup { my $c=shift; ($c>=0x61&&$c<=0x7a)?$c-32:$c }
sub cdn { my $c=shift; ($c>=0x41&&$c<=0x5a)?$c+32:$c }
my (@bu,@bd);
for my $c (1..255){ next if $c==0x0a;
  # branch A: byte is first (capitalize_next=true) -> toupper
  my $w=chr($c);
  my @o=`\Q$B\E 1 \Q$w\E`; my $g=$o[4]//""; $g=~s/\n\z//;
  my $e=chr(cup($c)); push @bu,sprintf("%02x->%s",$c,unpack("H*",$g)) if $g ne $e;
  # branch B: preceded by "X" so capitalize_next=false -> tolower
  my $w2="X".chr($c);
  my @o2=`\Q$B\E 1 \Q$w2\E`; my $g2=$o2[4]//""; $g2=~s/\n\z//;
  my $e2="X".chr(cdn($c)); push @bd,sprintf("%02x->%s(exp %s)",$c,unpack("H*",$g2),unpack("H*",$e2)) if $g2 ne $e2;
}
print "toupper-branch deviations: ", (@bu?join(" ",@bu):"NONE"), "\n";
print "tolower-branch deviations: ", (@bd?join(" ",@bd):"NONE"), "\n";'
